<script setup>
import { onMounted, proxyRefs } from 'vue'; import { useStockIntelligence } from '../../../composables/useStockIntelligence';
const stock=proxyRefs(useStockIntelligence()); onMounted(()=>stock.load());
</script>
<template><section class="stock-panel"><div class="stock-panel-head"><div><h2>Stock Intelligence</h2><p>Live ERP inventory, movement, forecast, batch, and asset reports.</p></div><button :disabled="stock.loading" @click="stock.load({force:true})">{{stock.loading?'Loading…':'↻ Refresh'}}</button></div><div class="stock-report-controls"><label>From<input v-model="stock.from" type="date"></label><label>To<input v-model="stock.to" type="date"></label><button :disabled="stock.loading" @click="stock.load">Run reports</button><label>Warehouse<input v-model="stock.warehouse" placeholder="All warehouses"></label><label>Search<input v-model="stock.query" type="search" placeholder="Item, client, or warehouse"></label></div><p v-if="stock.error" class="stock-error">{{stock.error}}</p><p v-if="stock.loading" class="stock-loading">Loading Stock Intelligence reports…</p><div v-for="table in stock.tables" :key="table.key" class="stock-intel-table"><h3>{{table.key.replaceAll(/([A-Z])/g,' $1').replaceAll('_',' ')}} · {{table.rows.length}}</h3><div class="stock-table-wrap"><table><thead><tr><th v-for="col in table.columns" :key="col.fieldname">{{col.label||col.fieldname}}</th></tr></thead><tbody><tr v-for="(row,index) in table.rows" :key="row.name||row.item_code||index"><td v-for="col in table.columns" :key="col.fieldname">{{row[col.fieldname]??'—'}}</td></tr></tbody></table></div></div><ul v-if="stock.failed.length" class="stock-warnings"><li v-for="message in stock.failed" :key="message">{{message}}</li></ul></section></template>
